from itertools import product
# Ground truth: some object is a book and no member has borrowed it.  Enumerate every model on a domain of N objects
# (each object may be a book and/or a member; Borrowed is any binary relation) and compare each option with the truth.
def run(N):
    objs = range(N)
    stat = lambda B, M, R: any(B[b] and not any(M[m] and R[m][b] for m in objs) for b in objs)
    opt = {
      "A": lambda B, M, R: any((not B[b]) or all((not M[m]) or (not R[m][b]) for m in objs) for b in objs),
      "B": lambda B, M, R: not any(B[b] and M[m] and R[m][b] for b in objs for m in objs),
      "C": lambda B, M, R: any(B[b] and all((not M[m]) or (not R[m][b]) for m in objs) for b in objs),
      "D": lambda B, M, R: all((not M[m]) or any(B[b] and not R[m][b] for b in objs) for m in objs),
    }
    bad = dict.fromkeys(opt, 0); tot = 0
    for B in product([0, 1], repeat=N):
        for M in product([0, 1], repeat=N):
            for flat in product([0, 1], repeat=N*N):
                R = [flat[i*N:(i+1)*N] for i in objs]
                t = stat(B, M, R); tot += 1
                for k, f in opt.items(): bad[k] += (f(B, M, R) != t)
    return tot, bad
for N in (2, 3):
    tot, bad = run(N); print(N, tot, bad)
    assert [k for k, v in bad.items() if v == 0] == ["C"]

